const MANAGEMENT_LABELS={CONTINUE_MONITORING:"ติดตามต่อ",CULTURAL_MANAGEMENT:"จัดการเชิงเขตกรรม",MECHANICAL_MANAGEMENT:"จัดการเชิงกล",BIOLOGICAL_MANAGEMENT:"ทบทวนทางเลือกชีวภาพ",EXPERT_REVIEW:"ต้องให้ผู้เชี่ยวชาญตรวจ",CHEMICAL_REVIEW:"ทบทวนการใช้สาร — ยังติดข้อกำกับ",NO_ACTION_CURRENTLY_JUSTIFIED:"ยังไม่ต้องลงมือในขณะนี้"};
const ELIGIBILITY_PRESENTATION={SUPPORTED_FOR_REVIEW:{selectable:true,state:"พร้อมให้ผู้ใช้พิจารณา",decision_state:"CONFIRMED"},HUMAN_REVIEW_REQUIRED:{selectable:true,state:"ต้องผ่านการทบทวนโดยมนุษย์",decision_state:"REVIEW_REQUIRED"},MORE_EVIDENCE_REQUIRED:{selectable:false,state:"ต้องมีหลักฐานเพิ่ม",decision_state:null},NOT_SUPPORTED_BY_CURRENT_EVIDENCE:{selectable:false,state:"หลักฐานปัจจุบันยังไม่รองรับ",decision_state:null},BLOCKED_BY_AUTHORITY:{selectable:false,state:"ยังติดข้อกำกับ",decision_state:null},NOT_APPLICABLE:{selectable:false,state:"ไม่ใช้กับบริบทนี้",decision_state:null}};
const ACTION_BLOCKED_OPTION_CLASSES=new Set(["CONTINUE_MONITORING","NO_ACTION_CURRENTLY_JUSTIFIED","CHEMICAL_REVIEW","EXPERT_REVIEW"]);

export class GovernedSpaRuntime {
  constructor({workspace,llm,idProvider=()=>globalThis.crypto.randomUUID()}={}){this.workspace=workspace;this.llm=llm;this.idProvider=idProvider;this.identity=null;this.lifecycleState={authority:"SERVER",fields:[],seasons:[]};this.capabilityState={capabilities:[]};this.caseState=null;this.due=[];}
  async synchronize(){const [session,lifecycle,capabilities]=await Promise.all([this.workspace.session(),this.workspace.lifecycle(),typeof this.workspace.capabilities==="function"?this.workspace.capabilities():Promise.resolve({capabilities:[]})]);this.identity=session.identity;this.lifecycleState=lifecycle;this.capabilityState=capabilities;await this.refreshDue();return{identity:this.identity,lifecycle,capabilities};}
  featureEnabled(feature){const item=this.capabilityState.capabilities?.find((entry)=>entry.feature===feature);return item?(item.availability?item.availability==="AVAILABLE":item.enabled===true):true;}
  captureOnly(){return this.capabilityState.capture_only===true||this.capabilityState.mode==="FIELD_CAPTURE_ALPHA";}
  scopeFor(field){if(!field||field.authority_state==="LOCAL_DRAFT"||!this.lifecycleState.fields.some((item)=>item.field_id===field.field_id&&item.season_id===field.season_id))return null;return{field_id:field.field_id,season_id:field.season_id};}
  presentFields(localFields=[]){const authoritative=this.lifecycleState.fields.map((field)=>({...field,authority_state:"SERVER_CONFIRMED"})),known=new Set(authoritative.map((item)=>item.field_id));return authoritative.concat(localFields.filter((item)=>!known.has(item.field_id)).map((item)=>({...item,authority_state:"LOCAL_DRAFT"})));}
  async createField(input){const result=await this.workspace.createField(input);await this.synchronize();return{...result.field,authority_state:"SERVER_CONFIRMED"};}
  async startCase(field,purpose="การตรวจจาก Primary SPA"){const scope=this.scopeFor(field);if(!scope)throw new Error("แปลงนี้ยังเป็นข้อมูลร่างบนอุปกรณ์ บันทึกแปลงบนระบบก่อนเริ่มเคส");const created=await this.workspace.createInvestigationRecord("CASE",{...scope,purpose});this.caseState={scope:{...scope,case_id:created.record.case_id},conversation_id:null};await this.refreshCase();return this.caseState;}
  async resumeCase(scope){if(!scope?.case_id||!this.lifecycleState.fields.some((item)=>item.field_id===scope.field_id&&item.season_id===scope.season_id))throw new Error("ไม่พบบริบทเคสที่ระบบยืนยัน");this.caseState={scope:{field_id:scope.field_id,season_id:scope.season_id,case_id:scope.case_id},conversation_id:null};await this.refreshCase();return this.caseState;}
  async captureStatement(text){if(!this.featureEnabled("conversation_provider"))throw new Error("ความสามารถการสนทนาถูกปิดโดยผู้ดูแลระบบ");if(!this.caseState?.scope)throw new Error("กรุณาเริ่มเคสที่บันทึกบนระบบก่อน");const result=await this.llm.chat({...this.caseState.scope,scope:"CASE_SCOPED",message:text});if(result.governed_response?.conversation_id)this.caseState.conversation_id=result.governed_response.conversation_id;await this.refreshCase();return result;}
  async refreshCase(){const scope=this.caseState?.scope;if(!scope)return null;const settled=await Promise.allSettled([this.workspace.getInvestigationBundle(scope),this.workspace.getInvestigationAssessment(scope),this.workspace.getGuidance(scope),this.workspace.getManagementOptions(scope),this.workspace.getDecisionActionOutcomeContext(scope),this.workspace.getFollowUpReminderContext(scope),this.workspace.getAuthoritativeTimeline(scope),this.workspace.getVisualEvidenceBundle(scope)]);const value=(index,fallback)=>settled[index].status==="fulfilled"?settled[index].value:fallback;Object.assign(this.caseState,{bundle:value(0,{observations:[],evidence:[]}),assessment:value(1,null),guidance:value(2,{guidance:null}),management:value(3,{all_option_evaluations:[]}),decision:value(4,{decisions:[],actions:[],outcomes:[]}),followUp:value(5,{plans:[],reminders:[]}),timeline:value(6,{events:[]}),visual:value(7,{images:[]}),degraded:settled.map((item,index)=>item.status==="rejected"?index:null).filter((item)=>item!=null)});return this.caseState;}
  async uploadPhoto(file,options={}){if(!this.caseState?.scope)throw new Error("กรุณาเริ่มเคสก่อนแนบภาพ");const observation=this.caseState.bundle?.observations?.at(-1),uploaded=await this.workspace.uploadVisualEvidence(file,this.caseState.scope,{observation_id:observation?.observation_id??null,guidance_id:this.caseState.guidance?.guidance?.guidance_id??null,...options});await this.refreshCase();return uploaded;}
  async manualPhotoReview(imageEvidenceId,{target="VISIBLE_FEATURE",state="UNKNOWN",basis="รอผู้ใช้หรือผู้ตรวจทบทวนภาพ",appropriate_view=false}={}){const result=await this.workspace.assessVisualEvidence(imageEvidenceId,{quality:{FOCUS:"UNKNOWN",EXPOSURE:"UNKNOWN"},observability:[{target,state,basis,appropriate_view}],features:[],assessment_method:"EXPLICIT_STRUCTURED_INPUT",assessment_version:"primary-spa-manual/v1"});await this.refreshCase();return result;}
  managementOptions(){if(!this.featureEnabled("f1_management_review"))return[];return(this.caseState?.management?.all_option_evaluations??this.caseState?.management?.options??[]).map((option)=>{const presentation=ELIGIBILITY_PRESENTATION[option.eligibility_state]??{selectable:false,state:"สถานะไม่รองรับ",decision_state:null};return{...option,label:MANAGEMENT_LABELS[option.option_class]??"ทางเลือกที่กำกับไว้",selectable:presentation.selectable,eligibility_label:presentation.state,decision_state_on_selection:presentation.decision_state,action_allowed:presentation.decision_state==="CONFIRMED"&&!ACTION_BLOCKED_OPTION_CLASSES.has(option.option_class)};});}
  currentDecision(){return this.caseState?.decision?.current_decision??null;}
  currentAction(){return(this.caseState?.decision?.current_management_actions??[]).at(-1)??null;}
  async selectManagementOption(option,rawText="ผู้ใช้ยืนยันทางเลือกนี้"){if(!this.featureEnabled("f1_management_review")||!this.featureEnabled("f2_management_action"))throw new Error("การทบทวนหรือบันทึกการตัดสินใจถูกปิดโดยผู้ดูแลระบบ");if(!option?.management_option_id||!option.selectable)throw new Error("ทางเลือกนี้ยังไม่เปิดให้บันทึกการตัดสินใจ");const review=this.caseState.management,scope=this.caseState.scope,type=option.option_class==="CONTINUE_MONITORING"?"CONTINUE_MONITORING":option.option_class==="NO_ACTION_CURRENTLY_JUSTIFIED"?"NO_ACTION_CURRENTLY":option.option_class==="EXPERT_REVIEW"?"REQUEST_EXPERT_REVIEW":"SELECT_MANAGEMENT_OPTION",current=this.currentDecision();const response=await this.workspace.createHumanDecision({request_id:`spa-decision-${this.idProvider()}`,...scope,management_review_id:review.management_review_id,decision_type:type,selected_option_id:option.management_option_id,selection_source:"AUTHENTICATED_UI",selection_raw_text:rawText,selection_source_span:{start:0,end:rawText.length,text:rawText},explicit_confirmation:true,expected_current_decision_id:current?.decision_id??null,supersedes_decision_id:current?.decision_id??null});await this.refreshCase();return response.decision??response;}
  async planAction(description){const decision=this.currentDecision(),current=this.currentAction();if(!this.featureEnabled("f2_management_action"))throw new Error("การบันทึก Management Action ถูกปิดโดยผู้ดูแลระบบ");if(!decision||decision.decision_state!=="CONFIRMED")throw new Error("ต้องมี Human Decision ที่ยืนยันแล้วก่อนวางแผน");if(decision.current_validity==="STALE")throw new Error("Decision เดิมล้าสมัย กรุณายืนยัน Decision ใหม่ก่อนวางแผน");if(ACTION_BLOCKED_OPTION_CLASSES.has(decision.selected_option_class))throw new Error("ทางเลือกนี้ไม่สร้าง Management Action ในขั้นนี้");const response=await this.workspace.createManagementAction({request_id:`spa-action-plan-${this.idProvider()}`,...this.caseState.scope,decision_id:decision.decision_id,action_kind:"PLAN",action_source:"HUMAN_AUTHORED_PLAN",action_description:String(description??"").trim(),action_parameters:{source:"PRIMARY_SPA_HUMAN_INPUT"},actor_source:"AUTHENTICATED_USER",limitations:["แผนนี้เป็นข้อความที่ผู้ใช้บันทึก ไม่ใช่คำแนะนำที่ระบบสร้าง"],explicit_confirmation:true,expected_current_action_id:current?.management_action_id??null,supersedes_action_id:current?.management_action_id??null});await this.refreshCase();return response.action??response;}
  async confirmPerformed(performedAt){const decision=this.currentDecision(),current=this.currentAction();if(!this.featureEnabled("f2_management_action"))throw new Error("การยืนยัน Management Action ถูกปิดโดยผู้ดูแลระบบ");if(decision?.current_validity==="STALE")throw new Error("Decision เดิมล้าสมัย กรุณายืนยัน Decision ใหม่ก่อนยืนยันการดำเนินการ");if(!decision||!current||current.status!=="PLANNED")throw new Error("ต้องมีแผนที่ยังไม่ได้ยืนยันการดำเนินการ");const response=await this.workspace.createManagementAction({request_id:`spa-action-performed-${this.idProvider()}`,...this.caseState.scope,decision_id:decision.decision_id,action_kind:"CONFIRM_PERFORMED",action_source:"HUMAN_EXECUTION_CONFIRMATION",action_description:current.action_description,action_parameters:current.action_parameters??{},planned_at:current.planned_at,performed_at:performedAt,actor_source:"AUTHENTICATED_USER",limitations:current.limitations??[],explicit_confirmation:true,expected_current_action_id:current.management_action_id,supersedes_action_id:current.management_action_id,management_event_type:"UNKNOWN_MANAGEMENT_EVENT"});await this.refreshCase();return response.action??response;}
  async recordOutcome(input={}){const decision=this.currentDecision(),action=this.currentAction();if(!decision||!action||action.status!=="PERFORMED")throw new Error("ต้องยืนยันการดำเนินการก่อนบันทึกผลติดตาม");const review=(this.caseState.decision?.current_outcome_reviews??[]).find((item)=>item.management_action_id===action.management_action_id),history=review?.observations??[],rawValue=String(input.raw_value??input.note??"").trim();if(!rawValue)throw new Error("กรุณาบันทึกสิ่งที่สังเกตได้");const response=await this.workspace.createOutcomeObservation({request_id:`spa-outcome-${this.idProvider()}`,...this.caseState.scope,decision_id:decision.decision_id,management_action_id:action.management_action_id,phase:input.phase??"T1",observed_at:input.observed_at,elapsed_relation_to_action:"AFTER_ACTION",subject:input.subject??"ข้อสังเกตหลังดำเนินการ",raw_value:rawValue,unit:input.unit??"ไม่ระบุ",denominator:input.denominator??"ไม่ระบุ",count_basis:input.count_basis??"คำบรรยายจากผู้ใช้",sample_size:input.sample_size??null,sampling_method:input.sampling_method??"การสังเกตโดยผู้ใช้",sampling_context:{source:"PRIMARY_SPA_HUMAN_INPUT"},spatial_scope:input.spatial_scope??"แปลงที่เลือก",visual_evidence_refs:[],source:"USER_SUBMITTED",evidence_state:"OBSERVED",limitations:["เป็นข้อสังเกตเชิงพรรณนา ไม่ยืนยันประสิทธิผลหรือเหตุเป็นผล"],explicit_submission:true,expected_outcome_revision:history.length});await this.refreshCase();return response.observation??response;}
  async transitionReminder(reminder,action){if(!["ACKNOWLEDGE","COMPLETE","DISMISS"].includes(action))throw new Error("สถานะการเตือนไม่รองรับ");const response=await this.workspace.actOnReminder({request_id:`spa-reminder-${this.idProvider()}`,reminder_id:reminder.reminder_id,action,expected_revision:reminder.revision});await this.refreshCase();await this.refreshDue();return response.reminder??response;}
  async refreshDue(){const results=await Promise.allSettled(this.lifecycleState.fields.map((field)=>this.workspace.getDueReminders({field_id:field.field_id,season_id:field.season_id})));this.due=results.flatMap((item)=>item.status==="fulfilled"?(item.value.due??[]):[]);return this.due;}
  async localPatterns(){if(!this.featureEnabled("step_h_local_pattern"))throw new Error("มุมมองรูปแบบในพื้นที่ถูกปิดโดยผู้ดูแลระบบ");const value=await this.workspace.getLocalPatternCandidates();return(value.candidates??[]).map((candidate)=>({...candidate,bounded_message:"มีเคสที่ข้อมูลบางส่วนเข้ากันได้ แต่ยังเรียกว่าเป็นการระบาดไม่ได้"}));}
  async nominateCase(rawDescription="เก็บเคสนี้ไว้เป็นความรู้"){if(!this.featureEnabled("step_i_learning"))throw new Error("การเสนอ Learning Candidate ถูกปิดโดยผู้ดูแลระบบ");const scope=this.caseState?.scope;if(!scope)throw new Error("กรุณาเปิดเคสก่อน");const response=await this.workspace.createLearningNomination({request_id:`spa-learning-${this.idProvider()}`,type:"KNOWLEDGE_GAP",source_type:"FIELD_CASE",field_id:scope.field_id,season_id:scope.season_id,case_id:scope.case_id,raw_description:rawDescription,structured_gap:{gap_code:"FIELD_CASE_REVIEW_NOMINATED"},proposed_scope:"bounded field case",supporting_refs:[scope.case_id],privacy_state:"REVIEW_REQUIRED",consent_or_usage_rights_state:"REVIEW_REQUIRED"}),nomination=response.nomination??response;return{...nomination,friendly_message:"เก็บเป็น Learning Candidate ไว้แล้วครับ ยังไม่เปลี่ยนความรู้หลักจนกว่าจะผ่านการตรวจ"};}
}

export function casePresentation(state){const assessment=state?.assessment,guidance=state?.guidance?.guidance??state?.guidance,visual=state?.visual?.images??[];return{known:(state?.bundle?.observations??[]).map((item)=>item.note).filter(Boolean),missing:assessment?.missing_evidence??assessment?.evidence_gaps??[],next_action:guidance?.how_to_inspect??guidance?.why_now??"บันทึกสิ่งที่เห็นตามจริงหรือแนบภาพเมื่อช่วยแยกข้อมูลได้",visual:visual.map((image)=>({id:image.image_evidence_id,level:image.ve_level,quality:image.quality_assessments?.at(-1)?.quality??null,observability:image.quality_assessments?.at(-1)?.observability??[],boundary:"ภาพที่รับแล้วไม่เท่ากับภาพที่วิเคราะห์ และไม่ใช่การวินิจฉัย"})),question_limit_per_turn:1,initial_question_limit:2};}
